import{F as e,I as t,Z as n,t as r}from"./chunks/framework.CJzTmXUT.js";var i=JSON.parse(`{"title":"File Tree Component","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/file-tree.md","filePath":"en/deep-dive/file-tree.md","lastUpdated":1793361935000}`),a={name:`deep-dive/file-tree.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="file-tree-component" tabindex="-1">File Tree Component <a class="header-anchor" href="#file-tree-component" aria-label="Permalink to “File Tree Component”">​</a></h1><p>File tree is a SolidJS component that visualizes an array of sync tasks, and enables selecting / deselecting tasks.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>Creates visual hierarchy (left padding) for different folder nesting levels.</p><p>Renders select box, Obsidian tooltip, icon, and task path</p><p>1 universal path compaction rule:</p><ul><li>if a folder only has one children in the task list, and the folder itself is not in the task list, the children and folder combines into one entry with path shown as <code>&lt;parent-basename&gt; / &lt;child-basename&gt;</code>. This applies to each two path segments, so continuous nesting chains can be joined continuously, only stop at shallowest common parent.</li></ul><p>Selection rules:</p><ul><li>Deselecting a delete task deselects ancestor delete-folder tasks; selecting a delete-folder task selects descendant delete tasks.</li><li>Deselecting a folder creation task deselects descendant creation tasks; selecting a creation task selects ancestor creation-folder tasks.</li><li>These rules cascade through all task ancestors and descendants.</li><li><code>Move</code> tasks follow creation-selection rules.</li><li>A move task is presented as a folder creation whenever any descendant move task is deselected; conversion is derived from current selection.</li></ul><p>Behavior: selecting / unselecting only, no collapsing, no expansion.</p><p>Select all / deselect all:</p><ul><li>This option is rendered in style similar to a normal tree node with a checkbox icon <code>folders</code>, and corresponding state text <code>selectAll</code> or <code>deselectAll</code>, positioned like a root node in the tree, above all task nodes.</li><li>When any of the tasks is selected, the action should be <code>deselectAll</code>. Only when none of the tasks is selected, action is <code>selectAll</code>.</li><li>The checkbox should show indeterminate state when tasks are partially selected, otherwise show checked / unchecked.</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><ol><li>Pre-process:</li></ol><p>First, build a prefix tree from task paths, then recursively compact single-child folders. The flattened visible tree stores task ancestor and descendant links for selection cascades.</p><ol start="2"><li>Rendering and selection:</li></ol><p>Flatten the compacted tree into a 1D array and store nodes in a <code>Record</code>. Selection lives in a Solid store; task conversions are derived from that selection.</p><p>The UI simply maps over the flat array and applies padding-left based on the depth property.</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};